-- =====================================================================
-- GridPulse | 03_application_tables.sql
-- ---------------------------------------------------------------------
-- Application (non-domain) tables.  Converted from
--   legacy-mysql/07_create_access_requests.sql
--   legacy-mysql/08_create_users.sql
--   legacy-mysql/09_create_query_requests.sql
-- plus new GridPulse tables for alerts, approval audit and benchmarks.
--
-- Plain PostgreSQL features only.
--
-- Conversion notes
--   * INT AUTO_INCREMENT      -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--     (BY DEFAULT so migrated rows can keep their original IDs; the
--     migration script then advances the identity sequence).
--   * ENUM(...)               -> VARCHAR + CHECK constraint
--   * DATETIME                -> TIMESTAMPTZ
--   * JSON                    -> JSONB
--   * ON UPDATE CURRENT_TIMESTAMP -> trigger set_updated_at()
--   * users.password_hash is intentionally NOT carried over: GridPulse
--     authenticates the two fixed demonstration accounts from backend
--     configuration (see backend/README.md).  app_users only stores the
--     identity so that requests, reviews and audits keep real foreign keys.
-- =====================================================================

\set ON_ERROR_STOP on
SET ROLE gridpulse_app;

BEGIN;

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- ============================================================
-- APP_USERS  (was: users)
-- ============================================================
CREATE TABLE app_users (
    user_id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(100) NOT NULL UNIQUE,
    role          VARCHAR(10)  NOT NULL DEFAULT 'USER',
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_login_at TIMESTAMPTZ,
    CONSTRAINT chk_app_users_role CHECK (role IN ('USER', 'ADMIN'))
);
CREATE TRIGGER trg_app_users_updated_at
    BEFORE UPDATE ON app_users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- ACCESS_REQUESTS
-- ============================================================
CREATE TABLE access_requests (
    request_id      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    requested_by    VARCHAR(100) NOT NULL,
    operation       VARCHAR(10)  NOT NULL,
    target_table    VARCHAR(100) NOT NULL,
    record_id       VARCHAR(255),
    request_data    JSONB,
    reason          VARCHAR(500),
    status          VARCHAR(10)  NOT NULL DEFAULT 'PENDING',
    reviewed_by     VARCHAR(100),
    reviewed_at     TIMESTAMPTZ,
    review_comment  VARCHAR(500),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT chk_access_requests_operation
        CHECK (operation IN ('CREATE', 'UPDATE', 'DELETE')),
    CONSTRAINT chk_access_requests_status
        CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED'))
);
CREATE INDEX idx_access_requests_status       ON access_requests (status);
CREATE INDEX idx_access_requests_requested_by ON access_requests (requested_by);
CREATE INDEX idx_access_requests_created_at   ON access_requests (created_at);
CREATE TRIGGER trg_access_requests_updated_at
    BEFORE UPDATE ON access_requests
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- QUERY_REQUEST  (Query Studio approval workflow)
-- ============================================================
CREATE TABLE query_request (
    request_id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    submitted_by      INTEGER     NOT NULL,
    reviewed_by       INTEGER,
    sql_query         TEXT        NOT NULL,
    query_type        VARCHAR(30) NOT NULL,
    status            VARCHAR(30) NOT NULL DEFAULT 'PENDING',
    submitted_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    reviewed_at       TIMESTAMPTZ,
    rejection_reason  VARCHAR(500),
    execution_result  TEXT,
    CONSTRAINT fk_query_request_submitted_by
        FOREIGN KEY (submitted_by) REFERENCES app_users (user_id),
    CONSTRAINT fk_query_request_reviewed_by
        FOREIGN KEY (reviewed_by) REFERENCES app_users (user_id),
    -- [GRIDPULSE] the lifecycle that was only documented in U/BILL is now
    -- enforced by the database.
    CONSTRAINT chk_query_request_status
        CHECK (status IN ('PENDING', 'APPROVED', 'EXECUTING', 'COMPLETED', 'FAILED', 'REJECTED'))
);
CREATE INDEX idx_query_request_status       ON query_request (status);
CREATE INDEX idx_query_request_submitted_by ON query_request (submitted_by);

-- ============================================================
-- APPROVAL_AUDIT  [GRIDPULSE]
-- ------------------------------------------------------------
-- One row per approval / rejection attempt, including attempts that
-- were refused because of a wrong approval password.  The approval
-- password itself is NEVER stored.
-- ============================================================
CREATE TABLE approval_audit (
    audit_id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    admin_user_id   INTEGER      REFERENCES app_users (user_id),
    admin_username  VARCHAR(100) NOT NULL,
    action          VARCHAR(20)  NOT NULL,
    target_type     VARCHAR(30)  NOT NULL,
    target_id       VARCHAR(100) NOT NULL,
    outcome         VARCHAR(30)  NOT NULL,
    detail          VARCHAR(1000),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT chk_audit_action  CHECK (action IN ('APPROVE', 'REJECT', 'VERIFY')),
    CONSTRAINT chk_audit_target  CHECK (target_type IN ('QUERY_REQUEST', 'ACCESS_REQUEST', 'APPROVAL_PAGE')),
    CONSTRAINT chk_audit_outcome CHECK (outcome IN
        ('SUCCESS', 'DENIED_INVALID_PASSWORD', 'DENIED_NOT_PENDING', 'NOT_FOUND', 'EXECUTION_FAILED'))
);
CREATE INDEX idx_approval_audit_created ON approval_audit (created_at DESC);

-- ============================================================
-- CONSUMPTION_ALERT  [GRIDPULSE]
-- ------------------------------------------------------------
-- Explainable, rule-based anomaly alerts.  An alert is an indicator
-- for investigation — never proof of fraud or equipment failure.
-- UNIQUE (meter_id, observation_start, alert_type) prevents duplicate
-- alerts for the same meter, observation and alert type.
-- ============================================================
CREATE TABLE consumption_alert (
    alert_id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    meter_id              INTEGER       NOT NULL,
    alert_type            VARCHAR(40)   NOT NULL,
    severity              VARCHAR(10)   NOT NULL,
    observation_start     TIMESTAMPTZ   NOT NULL,
    observation_end       TIMESTAMPTZ   NOT NULL,
    observation_label     VARCHAR(20)   NOT NULL DEFAULT 'DAY',
    observed_consumption  NUMERIC(14,4),
    baseline_average      NUMERIC(14,4),
    deviation_pct         NUMERIC(10,2),
    baseline_days         INTEGER,
    baseline_start        DATE,
    baseline_end          DATE,
    unit                  VARCHAR(10),
    explanation           TEXT          NOT NULL,
    recommended_action    TEXT          NOT NULL,
    status                VARCHAR(12)   NOT NULL DEFAULT 'NEW',
    rule_version          VARCHAR(40)   NOT NULL,
    thresholds            JSONB,
    created_at            TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ   NOT NULL DEFAULT now(),
    reviewed_at           TIMESTAMPTZ,
    reviewed_by           INTEGER REFERENCES app_users (user_id),
    resolved_at           TIMESTAMPTZ,
    resolved_by           INTEGER REFERENCES app_users (user_id),
    status_note           VARCHAR(1000),
    CONSTRAINT fk_alert_meter
        FOREIGN KEY (meter_id) REFERENCES meter (meter_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT chk_alert_type CHECK (alert_type IN
        ('HIGH_CONSUMPTION', 'LOW_CONSUMPTION', 'DATA_GAP')),
    CONSTRAINT chk_alert_severity CHECK (severity IN ('LOW', 'MODERATE', 'HIGH')),
    CONSTRAINT chk_alert_status   CHECK (status IN ('NEW', 'REVIEWED', 'RESOLVED')),
    CONSTRAINT chk_alert_window   CHECK (observation_end > observation_start),
    CONSTRAINT uq_alert_observation UNIQUE (meter_id, observation_start, alert_type)
);
CREATE INDEX idx_alert_status_created ON consumption_alert (status, created_at DESC);
CREATE INDEX idx_alert_observation    ON consumption_alert (observation_start DESC);
CREATE TRIGGER trg_alert_updated_at
    BEFORE UPDATE ON consumption_alert
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- BENCHMARK_RUN  [GRIDPULSE]
-- ------------------------------------------------------------
-- Stores MEASURED benchmark runs (Database Performance Lab).  Nothing
-- in this table is ever hand-written; rows are inserted by the backend
-- after it has executed and timed the queries.
-- ============================================================
CREATE TABLE benchmark_run (
    run_id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    started_at    TIMESTAMPTZ NOT NULL,
    finished_at   TIMESTAMPTZ NOT NULL,
    triggered_by  INTEGER REFERENCES app_users (user_id),
    status        VARCHAR(30) NOT NULL,
    repetitions   INTEGER     NOT NULL,
    warmup_runs   INTEGER     NOT NULL,
    environment   JSONB       NOT NULL,
    results       JSONB       NOT NULL
);
CREATE INDEX idx_benchmark_run_started ON benchmark_run (started_at DESC);

COMMIT;

\echo 'Application tables created. Next: 04_timescale_hypertable.sql'
